function heading(string $eyebrow,string $title,string $description,string $button='',string $href=''): void { ?><div class="page-heading"><div><p class="eyebrow"><?=e($eyebrow)?></p><h1><?=e($title)?></h1><p class="muted"><?=e($description)?></p></div><?php if($button):?><a class="btn primary" href="<?=e($href)?>">＋ <?=e($button)?></a><?php endif?></div><?php }
function emptyState(string $title,string $body,string $button='',string $href=''): void { ?><div class="empty-state"><div class="empty-icon">◈</div><h3><?=e($title)?></h3><p><?=e($body)?></p><?php if($button):?><a class="btn secondary" href="<?=e($href)?>"><?=e($button)?> →</a><?php endif?></div><?php }
function inputField(string $label,string $name,mixed $value='',string $type='text',bool $required=false,string $extra=''): void { ?><label><?=e($label)?><?=$required?' *':''?><input type="<?=e($type)?>" name="<?=e($name)?>" value="<?=e($value??'')?>" <?=$required?'required':''?> <?=$extra?>></label><?php }
